                `from_verse` INT,
                `to_book` VARCHAR(255),
                `to_chapter` INT,
                `to_verse_start` INT,
                `to_verse_end` INT,
                `votes` INT,
                INDEX (`from_book`),
                INDEX (`to_book`)
            );
            

